"""Permutation-group helpers for orbit-weighted root placements."""

from __future__ import annotations

import numpy as np


def closure(generators: list[np.ndarray]) -> np.ndarray:
    """Return every element of the group generated by vertex permutations.

    Breadth-first products of known elements with the generators; elements
    are compared by their bytes, so the result has no repetitions.
    """
    identity = np.arange(len(generators[0]), dtype=np.uint8)
    seen = {identity.tobytes()}
    elements = [identity]
    frontier = [identity]
    while frontier:
        block = np.array(frontier)
        frontier = []
        for generator in generators:
            for row in generator.astype(np.uint8)[block]:
                key = row.tobytes()
                if key not in seen:
                    seen.add(key)
                    frontier.append(row)
                    elements.append(row)
    return np.array(elements)


def orbit_representatives(group: np.ndarray, members: np.ndarray, n: int) -> list[tuple[int, int]]:
    """Return (least point, orbit size) for each orbit of a subgroup on range(n).

    The subgroup is given by the rows ``members`` of ``group``.
    """
    seen = np.zeros(n, dtype=bool)
    result = []
    for point in range(n):
        if seen[point]:
            continue
        orbit = np.unique(group[members, point])
        seen[orbit] = True
        result.append((point, len(orbit)))
    return result


def weighted_placements(group: np.ndarray, first: int, k: int, n: int) -> tuple[np.ndarray, np.ndarray]:
    """Return orbit representatives of k-tuples with first root ``first`` and their weights.

    ``group`` must fix ``first``. Along a stabilizer chain, each next root
    ranges over orbit representatives of the pointwise stabilizer of the
    roots chosen so far, and the weight multiplies by the orbit size. Two
    placements in one orbit have the same labeled root type and the same
    profile-pair edge counts, so a weighted sum over representatives equals
    the sum over all n^(k-1) placements.
    """
    roots: list[list[int]] = []
    weights: list[int] = []

    def extend(prefix: list[int], members: np.ndarray, weight: int) -> None:
        if len(prefix) == k:
            roots.append(prefix)
            weights.append(weight)
            return
        for point, size in orbit_representatives(group, members, n):
            extend(prefix + [point], members[group[members, point] == point], weight * size)

    extend([first], np.arange(len(group)), 1)
    return np.array(roots, dtype=np.int64), np.array(weights, dtype=np.int64)
